#!/usr/bin/env python3
"""
Replace placeholders in HWPX XML files with values from JSON.
Removes stale layout-cache elements from modified paragraphs.
"""
import json
import os
import re
import shutil
from lxml import etree

# Load JSON data
with open('/root/supplier_contact.json', 'r', encoding='utf-8') as f:
    data = json.load(f)

print("Loaded JSON data:")
for key, value in data.items():
    print(f"  {key}: {value}")

extracted = '/root/hwpx_work/template_extracted'

# Namespaces used in HWPX files
NSMAP = {
    'hp': 'http://www.hancom.co.kr/hwpml/2010/HWPML',
    'opf': 'http://www.idpf.org/2007/opf'
}

# Track modified paragraphs
modified_para_ids = set()

def process_xml_file(fpath):
    """Process a single XML file, replacing placeholders and removing cache elements."""
    parser = etree.XMLParser(remove_blank_text=False)
    tree = etree.parse(fpath, parser)
    root = tree.getroot()

    modified = False

    # Find all text elements that might contain placeholders
    # Placeholders are in the format {{KEY}}
    for elem in root.iter():
        if elem.text and '{{' in elem.text:
            original_text = elem.text
            new_text = original_text

            # Find all placeholders in this text node
            placeholders = re.findall(r'\{\{([^}]+)\}\}', new_text)

            for placeholder in placeholders:
                key = placeholder
                if key in data:
                    # Replace {{KEY}} with the value from JSON
                    new_text = new_text.replace(f'{{{{{key}}}}}', data[key])
                    print(f"  Replacing {{{{{key}}}}} with '{data[key]}' in {os.path.basename(fpath)}")
                    modified = True
                else:
                    print(f"  WARNING: Key '{key}' not found in JSON data")

            if new_text != original_text:
                elem.text = new_text

    if modified:
        # Find all paragraphs that had text modifications and remove their linesegarray elements
        # The structure is: <hp:p> contains <hp:run> contains <hp:t> with text
        # and <hp:linesegarray> is a sibling of <hp:run> within <hp:p>
        for p_elem in root.iter():
            # Check if this is a paragraph element
            if p_elem.tag == '{http://www.hancom.co.kr/hwpml/2010/HWPML}p':
                # Check if this paragraph contains modified text
                has_modified_text = False
                for t_elem in p_elem.iter():
                    if t_elem.tag == '{http://www.hancom.co.kr/hwpml/2010/HWPML}t':
                        if t_elem.text and any(key in t_elem.text for key in data.values()):
                            has_modified_text = True
                            break

                # If this paragraph has the modified text, remove linesegarray elements
                if has_modified_text:
                    for child in list(p_elem):
                        if child.tag == '{http://www.hancom.co.kr/hwpml/2010/HWPML}linesegarray':
                            print(f"  Removing stale linesegarray from paragraph {p_elem.get('id', 'unknown')}")
                            p_elem.remove(child)

    if modified:
        tree.write(fpath, encoding='UTF-8', xml_declaration=True, pretty_print=False)
        return True
    return False

# Process all XML files
print("\nProcessing XML files...")
files_modified = 0
for root_dir, dirs, files in os.walk(extracted):
    for fname in files:
        if fname.endswith('.xml'):
            fpath = os.path.join(root_dir, fname)
            with open(fpath, 'r', encoding='utf-8') as f:
                content = f.read()
            if '{{' in content:
                print(f"\nProcessing: {fpath}")
                if process_xml_file(fpath):
                    files_modified += 1
            else:
                print(f"\nSkipping (no placeholders): {fpath}")

print(f"\n\nTotal files modified: {files_modified}")
